import os
import queue
import threading
from typing import Iterator, Optional

import pyaudio
from google.cloud import speech


class StreamingSpeechToText:
    def __init__(
        self,
        language_code: str = "en-US",
        sample_rate: int = 16000,
        chunk_size: int = 1024,
        interim_results: bool = True,
    ):
        self.language_code = language_code
        self.sample_rate = sample_rate
        self.chunk_size = chunk_size
        self.interim_results = interim_results

        self.client = speech.SpeechClient()
        self.audio_queue: "queue.Queue[Optional[bytes]]" = queue.Queue()
        self._stop_event = threading.Event()
        self._audio_interface = pyaudio.PyAudio()
        self._stream = None

    def _audio_callback(self, in_data, frame_count, time_info, status):
        if self._stop_event.is_set():
            return (None, pyaudio.paComplete)
        self.audio_queue.put(in_data)
        return (None, pyaudio.paContinue)

    def _request_generator(self) -> Iterator[speech.StreamingRecognizeRequest]:
        while not self._stop_event.is_set():
            chunk = self.audio_queue.get()
            if chunk is None:
                return
            yield speech.StreamingRecognizeRequest(audio_content=chunk)

    def start(self) -> None:
        if self._stream is not None:
            return

        self._stream = self._audio_interface.open(
            format=pyaudio.paInt16,
            channels=1,
            rate=self.sample_rate,
            input=True,
            frames_per_buffer=self.chunk_size,
            stream_callback=self._audio_callback,
        )
        self._stream.start_stream()

    def stop(self) -> None:
        self._stop_event.set()
        self.audio_queue.put(None)
        if self._stream is not None:
            try:
                self._stream.stop_stream()
                self._stream.close()
            finally:
                self._stream = None
        if self._audio_interface is not None:
            try:
                self._audio_interface.terminate()
            finally:
                self._audio_interface = None

    def transcripts(self) -> Iterator[str]:
        config = speech.RecognitionConfig(
            encoding=speech.RecognitionConfig.AudioEncoding.LINEAR16,
            sample_rate_hertz=self.sample_rate,
            language_code=self.language_code,
            enable_automatic_punctuation=True,
        )
        streaming_config = speech.StreamingRecognitionConfig(
            config=config,
            interim_results=self.interim_results,
            single_utterance=False,
        )

        try:
            responses = self.client.streaming_recognize(
                config=streaming_config,
                requests=self._request_generator(),
            )
            for response in responses:
                if self._stop_event.is_set():
                    break
                for result in response.results:
                    if result.alternatives:
                        transcript = result.alternatives[0].transcript.strip()
                        if transcript:
                            yield transcript
        finally:
            self.stop()

    def __enter__(self):
        self.start()
        return self

    def __exit__(self, exc_type, exc, tb):
        self.stop()
        return False


def stream_microphone_transcripts(
    language_code: str = "en-US",
    sample_rate: int = 16000,
    chunk_size: int = 1024,
) -> Iterator[str]:
    recognizer = StreamingSpeechToText(
        language_code=language_code,
        sample_rate=sample_rate,
        chunk_size=chunk_size,
    )
    recognizer.start()
    return recognizer.transcripts()


if __name__ == "__main__":
    # Requires GOOGLE_APPLICATION_CREDENTIALS to be set for Google Cloud Speech-to-Text.
    try:
        for transcript in stream_microphone_transcripts():
            print(transcript)
    except KeyboardInterrupt:
        pass
